Get Patients.code:
// Get the first page of patients from the register.
// Authentication with email/password happens automatically.
getPatients();

Get Patients by Page.code:
// Get one page of patients.
getPatients({
  // Zero-based page index.
  page: $.data.page ?? 0,
  // Records per page.
  size: 100,
});

Search Patients.code:
// Find patients whose name or hospital number matches.
getPatients({
  // Free-text filter over name and hospital number.
  searchValue: $.data.hospitalNumber,
  size: 20,
});
